// Machine Console v0.1 — a read-only viewer over a pre-built JSON
// snapshot (data.json, regenerated by run_mobile_console.py from real
// ledgers). No fetch here ever uses a mutating method. No button here
// writes anything, anywhere. This is a viewer only, nothing further.

const SCREENS = ["home", "opportunities", "pipeline", "ground-truth", "activity"];
const TITLES = {
  home: "Machine Console",
  opportunities: "Opportunities",
  pipeline: "Pipeline",
  "ground-truth": "Ground Truth",
  activity: "Activity",
};

let DATA = null;
let lastMainRoute = "home";

function esc(s) {
  return String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
}

function fmtDate(iso) {
  if (!iso) return "—";
  const d = new Date(iso);
  if (isNaN(d)) return iso;
  return d.toLocaleDateString("en-US", { year: "numeric", month: "short", day: "numeric" });
}

function fmtDateTime(iso) {
  if (!iso) return "—";
  const d = new Date(iso);
  if (isNaN(d)) return iso;
  return d.toLocaleString("en-US", { year: "numeric", month: "short", day: "numeric", hour: "2-digit", minute: "2-digit" });
}

function timeAgo(iso) {
  if (!iso) return "—";
  const d = new Date(iso);
  if (isNaN(d)) return iso;
  const diffMs = Date.now() - d.getTime();
  const days = Math.floor(diffMs / 86400000);
  if (days <= 0) return "today";
  if (days === 1) return "1 day ago";
  if (days < 30) return `${days} days ago`;
  const months = Math.floor(days / 30);
  return months === 1 ? "1 month ago" : `${months} months ago`;
}

async function loadData() {
  const res = await fetch("data.json", { cache: "no-cache" });
  if (!res.ok) throw new Error(`data.json fetch failed: ${res.status}`);
  return res.json();
}

// ---------- HOME ----------
function renderHome() {
  const m = DATA.machine_status;
  const recentActivity = DATA.activity.slice(0, 6);
  const awaitingPgt = DATA.ground_truth.cases.filter((c) => c.status === "OPEN");
  const validating = DATA.opportunities.filter((o) => o.state && o.state !== "WATCH");

  return `
    <div class="stat-grid">
      <div class="stat-tile"><div class="n">${m.total_observations}</div><div class="k">OBSERVATIONS CAPTURED</div></div>
      <div class="stat-tile"><div class="n">${m.total_anomalies}</div><div class="k">ANOMALIES CLUSTERED</div></div>
      <div class="stat-tile"><div class="n">${m.total_candidates}</div><div class="k">BUSINESS CANDIDATES</div></div>
      <div class="stat-tile"><div class="n">${m.total_judgments}</div><div class="k">DETERMINISTIC JUDGMENTS</div></div>
    </div>

    <div class="card">
      <h2>Machine status</h2>
      <div class="fact-grid" style="gap:12px">
        <div class="row-meta" style="margin-top:0">
          <span class="pill"><span class="dot"></span>${m.candidates_past_watch} of ${m.total_candidates} candidates past WATCH</span>
        </div>
        <div class="row-meta">
          <span class="pill"><span class="dot"></span>${m.total_blind_analyses} blind analyses · ${m.total_falsifications} falsifications</span>
        </div>
        <div class="row-meta">
          <span class="pill state-watch"><span class="dot"></span>${m.prospective_cases_awaiting_outcome} of ${m.total_prospective_cases} prospective case(s) awaiting outcome</span>
        </div>
        <div class="row-meta">
          <span class="pill">last real activity ${esc(timeAgo(m.last_activity_at))}</span>
        </div>
      </div>
    </div>

    <div class="section-label">Business candidates past WATCH (${validating.length})</div>
    ${validating.length ? `<div class="list">${validating.map(candidateRow).join("")}</div>`
                         : `<div class="empty-state">No candidate has moved past WATCH yet.</div>`}

    <div class="section-label">Ground truth awaiting outcome (${awaitingPgt.length})</div>
    ${awaitingPgt.length ? `<div class="list">${awaitingPgt.map(groundTruthCard).join("")}</div>`
                          : `<div class="empty-state">No prospective case is currently open.</div>`}

    <div class="section-label">Recent activity</div>
    <div class="card">${activityList(recentActivity)}</div>

    <footer class="colophon">
      <span>generated from canonical ledgers</span>
      <span>${esc(fmtDate(m.last_activity_at))}</span>
    </footer>
  `;
}

// ---------- OPPORTUNITIES ----------
function candidateRow(o) {
  const statePill = o.state === "WATCH"
    ? `<span class="pill state-watch"><span class="dot"></span>WATCH</span>`
    : `<span class="pill state-validating"><span class="dot"></span>${esc(o.state)}</span>`;
  return `
    <a class="row" href="#/case/${encodeURIComponent(o.candidate_id)}">
      <div class="row-head">
        <span class="row-id">${esc(o.candidate_id)}</span>
        ${o.has_full_docket ? `<span class="pill docket">full docket</span>` : ""}
      </div>
      <div class="row-title">${esc(o.case_facts?.anomaly?.canonical_pattern || o.candidate_type || "—")}</div>
      <div class="row-meta">
        ${statePill}
        ${o.pain_severity ? `<span class="pill">${esc(o.pain_severity)} pain</span>` : ""}
        <span class="pill">${esc(fmtDate(o.created_at))}</span>
      </div>
    </a>
  `;
}

function renderOpportunities() {
  const items = DATA.opportunities;
  return `
    <div class="section-label">${items.length} real business candidates</div>
    <div class="list">${items.map(candidateRow).join("")}</div>
  `;
}

// ---------- PIPELINE ----------
function pipelineLabel(id) {
  const stage = (DATA.pipeline || []).find((s) => s.id === id);
  return stage ? stage.stage : id;
}

function renderPipeline() {
  const stages = DATA.pipeline;
  const max = Math.max(...stages.map((s) => s.count), 1);
  return `
    <div class="card">
      <h2>Observable funnel</h2>
      <div class="funnel">
        ${stages.map((s) => `
          <a class="funnel-item" href="#/pipeline/${encodeURIComponent(s.id)}">
            <div class="funnel-row">
              <span class="funnel-label">${esc(s.stage)}</span>
              <span class="funnel-count">${s.count}</span>
            </div>
            <div class="funnel-bar-track"><div class="funnel-bar-fill" style="width:${Math.max(2, (s.count / max) * 100)}%"></div></div>
          </a>
        `).join("")}
      </div>
    </div>
    <div class="not-reached-card">
      <div class="nr-label">What this is not</div>
      <p>These are direct counts over real ledger records only — no conversion rate, no percentage, no funnel-drop-off estimate. A stage with 0 records shows 0. Tap a row to see the real records behind its count.</p>
    </div>
  `;
}

// ---------- PIPELINE DRILL-DOWN ----------
const PIPELINE_ID_FIELD = {
  observations: "observation_id",
  anomalies: "anomaly_id",
  blind_analyses: "artifact_id",
  falsifications: "artifact_id",
  judgments: "judgment_id",
};

function pipelineListFor(id) {
  if (id === "candidates") return DATA.opportunities;
  if (id === "candidates_past_watch") {
    const ids = new Set(DATA.pipeline_records.candidates_past_watch);
    return DATA.opportunities.filter((o) => ids.has(o.candidate_id));
  }
  return DATA.pipeline_records[id] || [];
}

function artifactTitleAndMeta(kind, item) {
  switch (kind) {
    case "observations":
      return {
        title: item.process || item.observation_id,
        meta: [item.source, fmtDate(item.published_at)].filter(Boolean),
      };
    case "anomalies":
      return {
        title: item.canonical_pattern || item.anomaly_id,
        meta: [fmtDate(item.first_seen)].filter(Boolean),
        pillState: item.status,
      };
    case "blind_analyses":
      return {
        title: item.hidden_function || item.artifact_id,
        meta: [item.provider, item.model, fmtDate(item.created_at)].filter(Boolean),
      };
    case "falsifications":
      return {
        title: `${item.critic_provider || "—"} critique of ${item.target_artifact_id || "—"}`,
        meta: [`${item.findings_count} finding${item.findings_count === 1 ? "" : "s"}`, fmtDate(item.created_at)].filter(Boolean),
      };
    case "judgments":
      return {
        title: item.status,
        meta: [item.source_run_id ? `run ${item.source_run_id}` : null, fmtDate(item.created_at)].filter(Boolean),
        pillState: item.status,
      };
    default:
      return { title: "—", meta: [] };
  }
}

function artifactRow(kind, item) {
  const id = item[PIPELINE_ID_FIELD[kind]];
  const { title, meta, pillState } = artifactTitleAndMeta(kind, item);
  const statePill = pillState
    ? `<span class="pill ${pillState === "WATCH" ? "state-watch" : "state-validating"}"><span class="dot"></span>${esc(pillState)}</span>`
    : "";
  return `
    <a class="row" href="#/pipeline/${encodeURIComponent(kind)}/${encodeURIComponent(id)}">
      <div class="row-head">
        <span class="row-id">${esc(id)}</span>
      </div>
      <div class="row-title">${esc(title)}</div>
      <div class="row-meta">
        ${statePill}
        ${meta.map((m) => `<span class="pill">${esc(m)}</span>`).join("")}
      </div>
    </a>
  `;
}

function renderPipelineDrilldown(id) {
  const items = pipelineListFor(id);
  const label = pipelineLabel(id);
  const isCandidateKind = id === "candidates" || id === "candidates_past_watch";
  const rows = isCandidateKind ? items.map(candidateRow) : items.map((it) => artifactRow(id, it));
  return `
    <div class="section-label">${items.length} record${items.length === 1 ? "" : "s"} — ${esc(label)}</div>
    ${items.length ? `<div class="list">${rows.join("")}</div>` : `<div class="empty-state">No records yet.</div>`}
  `;
}

function fieldLabel(key) {
  return key.replace(/_/g, " ").replace(/\b\w/g, (c) => c.toUpperCase());
}

function formatFieldValue(v) {
  if (v == null || v === "") return "—";
  if (Array.isArray(v)) return v.length ? v.join(", ") : "—";
  return String(v);
}

function renderArtifactDetail(kind, itemId) {
  const idField = PIPELINE_ID_FIELD[kind];
  if (!idField) return `<div class="empty-state">Unknown record kind ${esc(kind)}.</div>`;
  const list = DATA.pipeline_records[kind] || [];
  const item = list.find((it) => String(it[idField]) === itemId);
  if (!item) return `<div class="empty-state">Unknown record ${esc(itemId)}.</div>`;
  return `
    <div class="docket-wrap">
      <div class="masthead">
        <div class="eyebrow">${esc(pipelineLabel(kind))}</div>
        <h1 style="font-size:19px;word-break:break-word">${esc(itemId)}</h1>
      </div>
      <div class="docket-card">
        <dl class="fact-grid">
          ${Object.entries(item).map(([k, v]) => `
            <div class="fact">
              <dt>${esc(fieldLabel(k))}</dt>
              <dd class="muted">${esc(formatFieldValue(v))}</dd>
            </div>
          `).join("")}
        </dl>
      </div>
    </div>
  `;
}

// ---------- GROUND TRUTH ----------
function groundTruthCard(c) {
  const total = new Date(c.expected_resolution_window.latest) - new Date(c.t0_cutoff);
  const elapsed = Date.now() - new Date(c.t0_cutoff);
  const pct = total > 0 ? Math.min(100, Math.max(0, (elapsed / total) * 100)) : 0;
  return `
    <div class="card gt-card">
      <div class="gt-head">
        <div class="gt-eyebrow">${esc(c.prospective_case_id)}${c.source_case_id ? ` · relates to ${esc(c.source_case_id)}` : ""}</div>
        <h3 style="font-size:15px;font-weight:560;line-height:1.35">${esc(c.domain)}</h3>
      </div>
      <div class="gt-prop">${esc(c.proposition)}</div>
      <div class="funnel-bar-track" style="margin:0 16px;width:auto"><div class="funnel-bar-fill" style="width:${pct}%;background:var(--watch-ring)"></div></div>
      <div class="gt-window">
        <span>T0 ${esc(fmtDate(c.t0_cutoff))}</span>
        <span>window opens ${esc(fmtDate(c.expected_resolution_window.earliest))}</span>
        <span>check by ${esc(fmtDate(c.expected_resolution_window.latest))}</span>
      </div>
      <div class="gt-window" style="padding-top:0">
        <span class="pill ${c.status === 'OPEN' ? 'state-watch' : ''}">${esc(c.status)}</span>
      </div>
    </div>
  `;
}

function renderGroundTruth() {
  const cases = DATA.ground_truth.cases;
  return `
    <div class="section-label">${cases.length} prospective case${cases.length === 1 ? "" : "s"}</div>
    ${cases.length ? cases.map(groundTruthCard).join("")
                    : `<div class="empty-state">No prospective case registered yet.</div>`}
    <div class="not-reached-card">
      <div class="nr-label">Independence</div>
      <p>Each case here is listed only under its own registered <code>source_case_id</code>. None is shown as a continuation of a Stage 4 case unless that specific link was declared at registration.</p>
    </div>
  `;
}

// ---------- ACTIVITY ----------
function activityList(items) {
  if (!items.length) return `<div class="empty-state">No activity recorded yet.</div>`;
  return items.map((a) => `
    <div class="activity-item">
      <span class="activity-dot kind-${esc(a.kind)}"></span>
      <div>
        <div class="activity-text">${esc(a.summary)}</div>
        <div class="activity-time">${esc(fmtDateTime(a.timestamp))} · ${esc(a.kind.replace(/_/g, " "))}</div>
      </div>
    </div>
  `).join("");
}

function renderActivity() {
  return `
    <div class="section-label">${DATA.activity.length} most recent real events</div>
    <div class="card">${activityList(DATA.activity)}</div>
  `;
}

// ---------- CASE DETAIL ----------
function renderCaseDetail(candidateId) {
  const o = DATA.opportunities.find((x) => x.candidate_id === candidateId);
  if (!o) return `<div class="empty-state">Unknown candidate ${esc(candidateId)}.</div>`;
  if (o.candidate_id === "BC-0001") return renderLoopInferenceCase(o);
  return renderGenericCaseDetail(o);
}

function renderGenericCaseDetail(o) {
  const f = o.case_facts;
  const obs = f.observations[0];
  return `
    <div class="docket-wrap">
      <div class="masthead">
        <div class="id-row">
          <span><b>candidate</b> ${esc(o.candidate_id)}</span>
          ${o.anomaly_ids.length ? `<span><b>anomaly</b> ${esc(o.anomaly_ids.join(", "))}</span>` : ""}
        </div>
      </div>
      <div class="docket">
        <div class="stage">
          <span class="stage-dot"></span>
          <p class="stage-label">Case</p>
          <div class="docket-card">
            <h2>${esc(f.anomaly?.canonical_pattern || "Case")}</h2>
            <dl class="fact-grid">
              ${obs ? `
                <div class="fact"><dt>Process</dt><dd>${esc(obs.process)}</dd></div>
                <div class="fact"><dt>In their own words</dt><blockquote class="quote">&ldquo;${esc(obs.evidence_quote)}&rdquo;</blockquote></div>
                <div class="fact"><dt>Why it matters</dt><dd class="muted">${esc(obs.pain)}</dd></div>
              ` : ""}
              ${f.dimensions.potential_product_function ? `
                <div class="fact">
                  <dt>Possible product function <span style="text-transform:none;letter-spacing:0;color:var(--ink-faint)">— ${esc(f.dimensions.potential_product_function.note || "interpretation")}</span></dt>
                  <dd class="muted">${(f.dimensions.potential_product_function.value || []).map(esc).join(" · ")}</dd>
                </div>
              ` : ""}
            </dl>
            <div class="evidence-strip">
              ${obs ? `<span>Source: <b style="color:var(--ink-muted)">${esc(obs.source)}</b></span><span>Captured ${esc(fmtDate(obs.published_at))}</span>` : ""}
              ${f.observations.length ? `<a href="${esc(obs.url)}" target="_blank" rel="noopener">${esc(obs.observation_id)} ↗</a>` : ""}
            </div>
          </div>
        </div>
        <div class="not-reached-card">
          <div class="nr-label">Not yet reached</div>
          <p>This candidate has not gone through blind independent analysis (Stage 3) or adversarial falsification and judgment (Stage 4). Only <code>BC-0001 / ANOM-0001</code> has, in this repo's real history so far — see its Case Detail for the full docket.</p>
        </div>
      </div>
    </div>
  `;
}

function renderLoopInferenceCase(o) {
  // Preserved exactly as first published — the one edit is the audited
  // "Business opportunity" paragraph below, which now cites BC-0001's
  // own real potential_product_function field (explicitly marked
  // "FRAMING ONLY" in that field's own source data) instead of a
  // synthesized paragraph with no canonical source.
  return `
  <div class="docket-wrap">
    <div class="masthead">
      <div class="eyebrow">Constraint Archaeology · adversarial review docket</div>
      <h1 style="font-size:26px">The Loop Inference Case</h1>
      <p style="max-width:60ch;color:var(--ink-muted);font-size:14px;margin:10px 0 0">One anomaly, followed end to end through blind independent analysis, cross-falsification, and a deterministic judgment — real data from the pipeline's first live run.</p>
      <div class="id-row">
        <span><b>case</b> 951963c3345d364c44c2f2ab34197651</span>
        <span><b>anomaly</b> ANOM-0001</span>
        <span><b>candidate</b> BC-0001</span>
        <span><b>run</b> 32142997999</span>
      </div>
    </div>

    <div class="docket">
      <div class="stage">
        <span class="stage-dot"></span>
        <p class="stage-label">01 · Case</p>
        <div class="docket-card">
          <h2>What happened</h2>
          <dl class="fact-grid">
            <div class="fact">
              <dt>Process</dt>
              <dd>Developing a probabilistic programming language with exact inference for loops — a personal project, underway since 2018.</dd>
            </div>
            <div class="fact">
              <dt>In their own words</dt>
              <blockquote class="quote">&ldquo;I didn't publicize it too much as performance was too abysmal to be practical.&rdquo;</blockquote>
            </div>
            <div class="fact">
              <dt>Why it matters</dt>
              <dd class="muted">A working, theoretically correct implementation has sat unpublicized for years — not because it's wrong, but because it's too slow to use. That gap between <em>correct</em> and <em>usable</em> is the whole shape of the anomaly.</dd>
            </div>
            <div class="fact">
              <dt>Business opportunity <span style="text-transform:none;letter-spacing:0;color:var(--ink-faint);font-family:'IBM Plex Mono',monospace;font-size:10.5px">— BC-0001's own recorded framing, not evidence</span></dt>
              <dd class="muted">BC-0001 (the real candidate wrapping this anomaly) records its <code style="font-family:'IBM Plex Mono',monospace;font-size:12px;background:var(--surface-sunk);padding:1px 5px;border-radius:4px">potential_product_function</code> as: “Manual performance optimization and feature additions (like integer support) required years of iterative work before tool became presentable” and “Performance optimization gap between theoretical capability (exact inference with loops) and practical usability prevented wider adoption and real-world validation.” BC-0001's own data marks this field <b>FRAMING ONLY — not evidence, must never by itself justify a state transition</b>. It stayed at WATCH.</dd>
            </div>
          </dl>
          <div class="evidence-strip">
            <span>Source: <b style="color:var(--ink-muted)">Hacker News</b></span>
            <span>Captured 2026-08-08</span>
            <span>1 independent source</span>
            <a href="https://github.com/kccqzy/probabilistic-program-inference/blob/master/README.md" target="_blank" rel="noopener">OBS-20260808-0004-19a7bc ↗</a>
            <span class="confidence-chip">sensor confidence 0.85</span>
          </div>
        </div>
      </div>

      <div class="stage">
        <span class="stage-dot"></span>
        <p class="stage-label">02 · Claims — independent, blind analysis</p>
        <div class="docket-card">
          <h2>Claude and GPT never saw each other's answer</h2>
          <div class="split">
            <div class="analyst claude">
              <div class="analyst-head"><span class="analyst-name">CLAUDE</span><span class="analyst-conf">confidence 0.92</span></div>
              <div class="claim disputed"><div class="claim-k">Hidden function</div><div class="claim-v">Execute probabilistic inference over loop constructs with exact, non-approximate guarantees.</div></div>
              <div class="claim"><div class="claim-k">Carrier</div><div class="claim-v">The runtime / inference engine itself — the algorithm, not the developer.</div></div>
              <div class="claim disputed"><div class="claim-k">Failure mechanism</div><div class="claim-v">Exact inference enumerates every possible execution path through a loop — state space grows exponentially with iteration count. The exponential blow-up <em>is</em> the theoretical correctness guarantee.</div></div>
              <div class="claim disputed"><div class="claim-k">Repair</div><div class="claim-v">Trade exactness for tractability — sampling, bounded unrolling, or state-space abstraction.</div></div>
            </div>
            <div class="analyst gpt">
              <div class="analyst-head"><span class="analyst-name">GPT</span><span class="analyst-conf">confidence 0.00</span></div>
              <div class="claim disputed"><div class="claim-k">Hidden function</div><div class="claim-v">Efficient execution of exact probabilistic inference over looping constructs.</div></div>
              <div class="claim"><div class="claim-k">Carrier</div><div class="claim-v">The developer, working on a personal project since 2018.</div></div>
              <div class="claim disputed"><div class="claim-k">Failure mechanism</div><div class="claim-v">Algorithmic and/or implementation inefficiency causes prohibitive execution time, despite theoretically correct results.</div></div>
              <div class="claim disputed"><div class="claim-k">Repair</div><div class="claim-v">Reduce execution time of exact inference with loops to within practical limits.</div></div>
            </div>
          </div>
          <div class="disagree-banner">
            <span class="count">3</span>
            <span class="text">material disagreements the deterministic diff found on its own — <b>hidden_function</b>, <b>failure_mechanism</b>, <b>repair</b> — before either model saw the other's answer.</span>
          </div>
        </div>
      </div>

      <div class="stage is-fork">
        <span class="stage-dot"></span>
        <p class="stage-label">03 · Falsification — each critiques only the other</p>
        <div class="docket-card">
          <h2>Cross-examination against the source, not each other's opinion</h2>
          <div class="fals-row">
            <div class="fals-card">
              <p class="fals-title"><b>Claude</b> critiquing GPT's reading</p>
              <div class="verdict-row"><span class="field">hidden_function</span><span class="verdict-tag supported">supported by source</span></div>
              <div class="verdict-row"><span class="field">failure_mechanism</span><span class="verdict-tag supported">supported by source</span></div>
              <div class="verdict-row"><span class="field">repair</span><span class="verdict-tag supported">supported by source</span></div>
              <div class="verdict-row"><span class="field">confidence</span><span class="verdict-tag insufficient">insufficient data</span></div>
            </div>
            <div class="fals-card">
              <p class="fals-title"><b>GPT</b> critiquing Claude's reading</p>
              <div class="verdict-row"><span class="field">hidden_function</span><span class="verdict-tag insufficient">insufficient data</span></div>
              <div class="verdict-row"><span class="field">failure_mechanism</span><span class="verdict-tag insufficient">insufficient data</span></div>
              <div class="verdict-row"><span class="field">repair</span><span class="verdict-tag insufficient">insufficient data</span></div>
              <div class="verdict-row"><span class="field">confidence</span><span class="verdict-tag ambiguity">schema ambiguity</span></div>
            </div>
          </div>
          <div class="missing-evidence">
            <h3>What the source evidence doesn't settle</h3>
            <ul>
              <li>The forum post never explicitly names exponential state-space enumeration as the cause — Claude's mechanism is a plausible inference from the domain, not something the poster stated outright.</li>
              <li>The poster says performance was too poor to use, but never says what would fix it — "reduce execution time" and "use approximate inference" are both readings the source is silent on.</li>
              <li>Neither model's "hidden function" is a phrase the source itself uses — both are interpretations of a two-sentence forum comment, which is exactly why the judge can't treat either as settled.</li>
            </ul>
          </div>
        </div>
      </div>

      <div class="stage">
        <span class="stage-dot"></span>
        <p class="stage-label">04 · Judgment</p>
        <div class="judgment-card">
          <div class="stamp-row">
            <span class="stamp">WATCH</span>
            <p class="judgment-reason">Unresolved material disagreement on <b>failure_mechanism</b>, <b>hidden_function</b>, and <b>repair</b> — neither Falsifier resolved either reading to a shared, uncontested account of the source. Not enough to reject; too much left open to advance.</p>
          </div>
          <div class="judgment-meta">
            <span><b>judgment</b> 9eb42302dfa829c81584e70fbd3fc3c2</span>
            <span><b>decided by</b> a pure function, zero model calls</span>
            <span><b>persisted</b> 2026-08-18</span>
          </div>
        </div>
      </div>
    </div>

    <div class="exhibit-divider"><span>Exhibit B — a different case, same next step</span><div class="line"></div></div>
    <p class="exhibit-note">This particular WATCH — one anonymous developer's side project — has no company changelog or public docket that could ever settle it later, so it stops here. But the mechanism a WATCH verdict is <em>for</em> — go quiet, wait for reality, come back — is already live on a case that does have one. See <a href="#/case/pgt-0001" style="color:var(--case-accent)">Ground Truth</a> for <code>PGT-0001</code>, a different real, registered case that demonstrates it — not a continuation of this one.</p>
  </div>
  `;
}

// ---------- ROUTER ----------
function currentRoute() {
  const hash = location.hash.replace(/^#\/?/, "");
  return hash || "home";
}

function render() {
  const route = currentRoute();
  const screenEl = document.getElementById("screen");
  const titleEl = document.getElementById("screen-title");
  const eyebrowEl = document.getElementById("eyebrow");

  if (!DATA) {
    screenEl.innerHTML = `<div class="loading">loading real ledger data…</div>`;
    return;
  }

  let html = "";
  if (route === "home") { html = renderHome(); titleEl.textContent = "Machine Console"; eyebrowEl.textContent = "discovery-lab · machine console"; lastMainRoute = "home"; }
  else if (route === "opportunities") { html = renderOpportunities(); titleEl.textContent = "Opportunities"; eyebrowEl.textContent = `${DATA.opportunities.length} business candidates`; lastMainRoute = "opportunities"; }
  else if (route === "pipeline") { html = renderPipeline(); titleEl.textContent = "Pipeline"; eyebrowEl.textContent = "observable funnel · real counts only"; lastMainRoute = "pipeline"; }
  else if (route.startsWith("pipeline/")) {
    const rest = route.slice("pipeline/".length);
    const slashIdx = rest.indexOf("/");
    if (slashIdx === -1) {
      const pid = decodeURIComponent(rest);
      html = renderPipelineDrilldown(pid);
      titleEl.textContent = pipelineLabel(pid);
      eyebrowEl.innerHTML = `<a href="#/pipeline" style="color:var(--case-accent);text-decoration:none">‹ back</a>`;
    } else {
      const pid = decodeURIComponent(rest.slice(0, slashIdx));
      const itemId = decodeURIComponent(rest.slice(slashIdx + 1));
      html = renderArtifactDetail(pid, itemId);
      titleEl.textContent = "Record Detail";
      eyebrowEl.innerHTML = `<a href="#/pipeline/${encodeURIComponent(pid)}" style="color:var(--case-accent);text-decoration:none">‹ back</a>`;
    }
  }
  else if (route === "ground-truth") { html = renderGroundTruth(); titleEl.textContent = "Ground Truth"; eyebrowEl.textContent = "prospective cases · independent of Stage 4"; lastMainRoute = "ground-truth"; }
  else if (route === "activity") { html = renderActivity(); titleEl.textContent = "Activity"; eyebrowEl.textContent = "real timestamped events"; lastMainRoute = "activity"; }
  else if (route.startsWith("case/")) {
    const id = decodeURIComponent(route.slice(5));
    html = renderCaseDetail(id);
    titleEl.textContent = "Case Detail";
    eyebrowEl.innerHTML = `<a href="#/${lastMainRoute}" style="color:var(--case-accent);text-decoration:none">‹ back</a>`;
  } else {
    html = `<div class="empty-state">Not found.</div>`;
  }

  screenEl.innerHTML = html;
  screenEl.scrollTop = 0;
  window.scrollTo(0, 0);

  document.querySelectorAll(".navbtn").forEach((btn) => {
    btn.setAttribute("aria-current", btn.dataset.route === lastMainRoute && SCREENS.includes(route) ? "page" : "false");
  });
}

document.querySelectorAll(".navbtn").forEach((btn) => {
  btn.addEventListener("click", () => { location.hash = `#/${btn.dataset.route}`; });
});
window.addEventListener("hashchange", render);

// ---------- BOOT ----------
loadData()
  .then((data) => { DATA = data; render(); })
  .catch((err) => {
    document.getElementById("screen").innerHTML = `<div class="empty-state">Could not load data.json: ${esc(err.message)}</div>`;
  });

if ("serviceWorker" in navigator) {
  window.addEventListener("load", () => {
    navigator.serviceWorker.register("sw.js").catch(() => {});
  });
}
